(function() {
  'use strict';

  (function applyPackageFromUrl() {
    var params = new URLSearchParams(window.location.search);
    var key = (params.get('package') || '').toLowerCase().trim();
    var map = { matzpen: 'מצפן', har: 'הרפתקה', ody: 'אודיסיאה' };
    var label = map[key];
    var h = document.getElementById('f_package');
    var subj = document.getElementById('f_subject');
    var banner = document.getElementById('packageBanner');
    var bannerLab = document.getElementById('packageBannerLabel');
    var formBanner = document.getElementById('formPackageBanner');
    var formBannerLab = document.getElementById('formPackageBannerLabel');
    if (label && h) {
      h.value = label;
      if (subj) subj.value = 'שאלון טיול משפחתי | ' + label + ' | מתי טסים';
      if (bannerLab) bannerLab.textContent = label;
      if (formBannerLab) formBannerLab.textContent = label;
      if (banner) banner.style.display = 'block';
      /* Shown again inside .form-wrap on narrow viewports (CSS hides on desktop) */
      if (formBanner) formBanner.style.display = 'block';
    }
  })();

  var currentStep = 1;
  var totalSteps = 3;

  function waDigitsOnly(val) {
    return String(val || '').replace(/\D/g, '');
  }

  function showWaError(msg) {
    var wa = document.getElementById('f_wa');
    var err = document.getElementById('f_wa_error');
    if (err) {
      err.textContent = msg;
      err.classList.add('show');
    }
    if (wa) wa.classList.add('input-invalid');
  }

  function clearWaError() {
    var wa = document.getElementById('f_wa');
    var err = document.getElementById('f_wa_error');
    if (err) err.classList.remove('show');
    if (wa) wa.classList.remove('input-invalid');
  }

  function validateWhatsAppField() {
    var wa = document.getElementById('f_wa');
    if (!wa) return false;
    var raw = wa.value.trim();
    if (!raw) {
      showWaError('נא להזין מספר וואטסאפ');
      return false;
    }
    if (/[a-zA-Z\u0590-\u05FF]/.test(raw)) {
      showWaError('רק ספרות — לא ניתן להזין אותיות');
      return false;
    }
    var digits = waDigitsOnly(raw);
    if (!digits) {
      showWaError('נא להזין מספר עם ספרות בלבד');
      return false;
    }
    if (digits.startsWith('972')) {
      if (digits.length !== 12 || digits.charAt(3) !== '5') {
        showWaError('מספר עם קידומת 972: 12 ספרות (9725XXXXXXXX)');
        return false;
      }
    } else if (digits.startsWith('0')) {
      if (digits.length !== 10 || digits.substring(0, 2) !== '05') {
        showWaError('מספר ישראלי: 10 ספרות, מתחיל ב-05');
        return false;
      }
    } else if (digits.startsWith('5')) {
      if (digits.length !== 9) {
        showWaError('מספר נייד: 9 ספרות (5XXXXXXXX) או 10 עם 0 בהתחלה');
        return false;
      }
    } else {
      showWaError('מספר לא תקין — השתמשו בפורמט 05XXXXXXXX');
      return false;
    }
    wa.value = digits;
    clearWaError();
    return true;
  }

  (function initWhatsAppField() {
    var wa = document.getElementById('f_wa');
    if (!wa) return;
    wa.addEventListener('input', function() {
      var cleaned = waDigitsOnly(this.value).slice(0, 12);
      if (this.value !== cleaned) this.value = cleaned;
      if (cleaned) clearWaError();
    });
    wa.addEventListener('paste', function(e) {
      e.preventDefault();
      var pasted = (e.clipboardData || window.clipboardData).getData('text') || '';
      this.value = waDigitsOnly(pasted).slice(0, 12);
      clearWaError();
    });
    wa.addEventListener('blur', function() {
      if (this.value.trim()) validateWhatsAppField();
    });
  })();

  function updateStepper(n) {
    var stepper = document.getElementById('stepper');
    if (!stepper) return;
    stepper.querySelectorAll('.stepper__item').forEach(function(item) {
      var s = Number(item.getAttribute('data-step'));
      item.classList.remove('stepper__item--active', 'stepper__item--done');
      if (s < n) item.classList.add('stepper__item--done');
      else if (s === n) item.classList.add('stepper__item--active');
    });
  }

  function goStep(n) {
    // validate step 1
    if (currentStep === 1 && n > 1) {
      var name = document.getElementById('f_name');
      var wa   = document.getElementById('f_wa');
      var ok = true;
      if (!name.value.trim()) { name.style.borderColor = '#e55'; ok = false; }
      else name.style.borderColor = '';
      if (!validateWhatsAppField()) ok = false;
      if (!ok) {
        if (!name.value.trim()) name.focus();
        else wa.focus();
        return;
      }
    }
    // validate step 2
    if (currentStep === 2 && n > 2) {
      var dest = document.getElementById('f_dest');
      if (!dest.value.trim()) { dest.style.borderColor = '#e55'; dest.focus(); return; }
      else dest.style.borderColor = '';
    }

    document.getElementById('step' + currentStep).classList.remove('active');
    currentStep = n;
    var stepEl = document.getElementById('step' + currentStep);
    stepEl.classList.add('active');

    var pct = Math.round((currentStep / totalSteps) * 100);
    document.getElementById('progressFill').style.width = pct + '%';
    document.getElementById('progressLabel').textContent = 'שלב ' + currentStep + ' מתוך ' + totalSteps;
    updateStepper(currentStep);

    function scrollActiveStepNavIntoView() {
      if (!stepEl) return;
      var nav = stepEl.querySelector('.step-nav');
      if (nav) {
        nav.scrollIntoView({ behavior: 'smooth', block: 'end' });
      } else {
        stepEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }
    window.requestAnimationFrame(function() {
      window.requestAnimationFrame(scrollActiveStepNavIntoView);
    });
  }
  window.goStep = goStep;

  (function initDestQuickPicks() {
    var destInput = document.getElementById('f_dest');
    var wrap = document.getElementById('destQuicks');
    var panel = document.getElementById('destPanel');
    var showAllBtn = document.getElementById('destShowAll');
    if (!destInput || !wrap) return;

    var buttons = wrap.querySelectorAll('.dest-quick');
    var featuredCount = 8;
    buttons.forEach(function(btn, i) {
      if (i >= featuredCount) btn.classList.add('dest-quick--extra');
      var check = document.createElement('span');
      check.className = 'dest-quick__check';
      check.setAttribute('aria-hidden', 'true');
      check.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';
      btn.appendChild(check);
    });
    if (showAllBtn) {
      var extraCount = Math.max(0, buttons.length - featuredCount);
      showAllBtn.textContent = extraCount ? 'עוד יעדים (' + extraCount + ')' : '';
      showAllBtn.style.display = extraCount ? '' : 'none';
      showAllBtn.addEventListener('click', function() {
        if (panel) panel.classList.add('is-expanded');
      });
    }

    function parseDestList(val) {
      return String(val || '')
        .split(/[,،]/)
        .map(function(s) { return s.trim(); })
        .filter(Boolean);
    }

    function writeDestList(list) {
      destInput.value = list.join(', ');
    }

    function getSelectedFromButtons() {
      var out = [];
      buttons.forEach(function(btn) {
        if (btn.getAttribute('aria-pressed') === 'true') {
          out.push(btn.getAttribute('data-dest') || '');
        }
      });
      return out;
    }

    function syncInputFromButtons() {
      writeDestList(getSelectedFromButtons());
      destInput.style.borderColor = '';
    }

    function syncPressedFromInput() {
      var parts = parseDestList(destInput.value);
      buttons.forEach(function(btn) {
        var d = btn.getAttribute('data-dest') || '';
        btn.setAttribute('aria-pressed', parts.indexOf(d) >= 0 ? 'true' : 'false');
      });
    }

    buttons.forEach(function(btn) {
      btn.addEventListener('click', function() {
        var pressed = btn.getAttribute('aria-pressed') === 'true';
        btn.setAttribute('aria-pressed', pressed ? 'false' : 'true');
        syncInputFromButtons();
      });
    });
    destInput.addEventListener('input', syncPressedFromInput);
  })();

  (function initInterestCards() {
    var cards = document.querySelectorAll('.interest');
    cards.forEach(function(card) {
      var check = document.createElement('span');
      check.className = 'interest__check';
      check.setAttribute('aria-hidden', 'true');
      check.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';
      card.appendChild(check);
    });
  })();

  // Kids add/remove
  var kidCount = 1;

  function createKidRow(num, removable) {
    var row = document.createElement('div');
    row.className = 'kid-row-simple';
    var badge = document.createElement('div');
    badge.className = 'kid-badge';
    badge.textContent = num;
    var inp = document.createElement('input');
    inp.type = 'text';
    inp.name = 'ילד ' + num + ' גיל';
    inp.placeholder = 'למשל: ' + (num + 4);
    row.appendChild(badge);
    row.appendChild(inp);
    if (removable) {
      var rem = document.createElement('button');
      rem.type = 'button';
      rem.className = 'btn-remove';
      rem.textContent = '−';
      rem.addEventListener('click', function() { row.remove(); renumber(); });
      row.appendChild(rem);
    }
    return row;
  }

  function setKidRows(target) {
    var container = document.getElementById('kidsSimple');
    var current = container.querySelectorAll('.kid-row-simple').length;
    if (target > current) {
      for (var i = current + 1; i <= target; i++) {
        container.appendChild(createKidRow(i, true));
      }
    } else if (target < current) {
      var rows = container.querySelectorAll('.kid-row-simple');
      for (var j = rows.length - 1; j >= target; j--) {
        rows[j].remove();
      }
    }
    kidCount = container.querySelectorAll('.kid-row-simple').length;
    // show/hide manual add button - only for 4+ selection
    var selected = document.querySelector('input[name="כמה ילדים"]:checked');
    document.getElementById('addKidSimple').style.display = (selected && selected.value === '4+') ? '' : 'none';
  }

  // Listen to radio changes
  document.querySelectorAll('input[name="כמה ילדים"]').forEach(function(radio) {
    radio.addEventListener('change', function() {
      var val = this.value;
      if (val === '1') setKidRows(1);
      else if (val === '2') setKidRows(2);
      else if (val === '3') setKidRows(3);
      else if (val === '4+') setKidRows(4);
    });
  });

  // Init: 1 child selected, hide add button
  setKidRows(1);

  document.getElementById('addKidSimple').addEventListener('click', function() {
    kidCount++;
    document.getElementById('kidsSimple').appendChild(createKidRow(kidCount, true));
  });

  function renumber() {
    document.querySelectorAll('#kidsSimple .kid-row-simple').forEach(function(r, i) {
      r.querySelector('.kid-badge').textContent = i + 1;
      r.querySelector('input').name = 'ילד ' + (i + 1) + ' גיל';
    });
    kidCount = document.querySelectorAll('#kidsSimple .kid-row-simple').length;
  }

  // Submit
  document.getElementById('tripForm').addEventListener('submit', async function(e) {
    e.preventDefault();
    if (!validateWhatsAppField()) {
      goStep(1);
      document.getElementById('f_wa').focus();
      return;
    }
    var btn = this.querySelector('.btn-submit');
    btn.textContent = '⏳ שולח...';
    btn.disabled = true;
    try {
      var res = await fetch(this.action, {
        method: 'POST',
        body: new FormData(this),
        headers: { 'Accept': 'application/json' }
      });
      if (res.ok) {
        this.style.display = 'none';
        document.getElementById('successBox').classList.add('show');
        var pw = document.querySelector('.progress-wrap');
        if (pw) pw.style.display = 'none';
        window.scrollTo({ top: 0, behavior: 'smooth' });
      } else { throw new Error(); }
    } catch {
      btn.textContent = 'שלחו 🚀';
      btn.disabled = false;
      alert('אירעה שגיאה. נסו שוב או פנו אלינו ישירות בוואטסאפ.');
    }
  });

  // Nav
  var nav = document.getElementById('nav');
  if (nav) window.addEventListener('scroll', function() { nav.classList.toggle('scrolled', window.scrollY > 10); }, { passive: true });

  // Rotating live weather in menu
  var WEATHER_CITIES = [
    { name: 'לונדון',    lat: 51.51, lon: -0.12 },
    { name: 'בודפשט',   lat: 47.50, lon: 19.04 },
    { name: 'וינה',      lat: 48.21, lon: 16.37 },
    { name: 'אתונה',     lat: 37.98, lon: 23.73 },
    { name: 'פראג',      lat: 50.08, lon: 14.44 },
    { name: 'ורשה',      lat: 52.23, lon: 21.01 },
    { name: 'ברטיסלבה', lat: 48.15, lon: 17.11 },
    { name: 'ברצלונה',  lat: 41.39, lon:  2.17 },
    { name: 'אמסטרדם',  lat: 52.37, lon:  4.90 },
    { name: 'רומא',      lat: 41.90, lon: 12.49 },
  ];
  var weatherCityIndex = Math.floor(Math.random() * WEATHER_CITIES.length);

  function fetchMenuWeather() {
    var el = (document.getElementById("__legacy_menuWeatherSnippet") || document.createElement("span"));
    if (!el) return;
    weatherCityIndex = (weatherCityIndex + 1) % WEATHER_CITIES.length;
    var city = WEATHER_CITIES[weatherCityIndex];
    el.textContent = city.name + '...';
    fetch('https://api.open-meteo.com/v1/forecast?latitude=' + city.lat + '&longitude=' + city.lon + '&current_weather=true')
      .then(function(r) { return r.json(); })
      .then(function(d) {
        var t = Math.round(d.current_weather.temperature);
        var code = d.current_weather.weathercode;
        var icon = code <= 1 ? '☀️' : code <= 3 ? '⛅' : code <= 67 ? '🌧' : '❄️';
        el.textContent = city.name + ' עכשיו ' + t + '°C ' + icon;
      })
      .catch(function() { el.textContent = 'מזג אוויר באירופה'; });
  }

  var hamburger = (document.getElementById("__legacy_hamburgerBtn") || document.createElement("button"));
  var mobileMenu = (document.getElementById("__legacy_mobileMenu") || document.createElement("div"));
  if (hamburger && mobileMenu) {
    hamburger.addEventListener('click', function(e) {
      e.stopPropagation();
      var isOpen = mobileMenu.classList.toggle('open');
      hamburger.setAttribute('aria-expanded', isOpen.toString());
      hamburger.setAttribute('aria-label', isOpen ? 'סגור תפריט' : 'פתח תפריט');
      document.body.style.overflow = isOpen ? 'hidden' : '';
      if (isOpen) fetchMenuWeather();
    });
    mobileMenu.querySelectorAll('a').forEach(function(link) {
      link.addEventListener('click', function() {
        mobileMenu.classList.remove('open');
        hamburger.setAttribute('aria-expanded', 'false');
        hamburger.setAttribute('aria-label', 'פתח תפריט');
        document.body.style.overflow = '';
      });
    });
    document.addEventListener('keydown', function(e) {
      if (e.key !== 'Escape') return;
      if (!mobileMenu.classList.contains('open')) return;
      mobileMenu.classList.remove('open');
      hamburger.setAttribute('aria-expanded', 'false');
      hamburger.setAttribute('aria-label', 'פתח תפריט');
      document.body.style.overflow = '';
      hamburger.focus();
    });
  }
})();
